import urllib.request, urllib.parse, json
base='https://geo.salvador.ba.gov.br/imageserver/rest/services/Hosted/mdt_apcp_centro_reclass_10m_r/ImageServer'
def load(url):
 req=urllib.request.Request(url,headers={'User-Agent':'Mozilla/5.0'})
 try:
  with urllib.request.urlopen(req,timeout=20) as r:
   raw=r.read().decode('utf-8','replace');
   try:return json.loads(raw)
   except:return {'_raw':raw[:2000]}
 except Exception as e:return {'_error':repr(e)}
meta=load(base+'?f=pjson')
print('META_KEYS',sorted(meta.keys()))
for k in sorted(meta.keys()):
 if any(x in k.lower() for x in ['raster','color','attribute','function','pixel','mosaic','serviceitem','copyright','description']): print('META_FIELD',k,meta.get(k))
for ep in ['rasterAttributeTable','colormap','info/metadata']:
 d=load(base+'/'+ep+'?f=pjson'); print('ENDPOINT',ep,json.dumps(d,ensure_ascii=False)[:5000])
# Search ArcGIS content for exact service/title and APCP-related images.
queries=['mdt_apcp_centro','apcp centro mdt','owner:sefazadmin apcp','owner:sefazadmin centro type:"Image Service"']
for q in queries:
 u='https://www.arcgis.com/sharing/rest/search?'+urllib.parse.urlencode({'q':q,'f':'json','num':100})
 d=load(u); print('SEARCH',q,'TOTAL',d.get('total'))
 for it in d.get('results',[]): print('ITEM',it.get('id'),it.get('type'),it.get('owner'),repr(it.get('title')),'URL',it.get('url'))
# Probe likely raw source service names (hidden services can still resolve directly).
for name in ['mdt_apcp_centro','mdt_apcp_centro_r','mdt_apcp_centro_05m','mdt_apcp_centro_0_5m','mdt_apcp_centro_reclass_10m','mdt_apcp_centro_reclass']:
 u='https://geo.salvador.ba.gov.br/imageserver/rest/services/Hosted/'+name+'/ImageServer?f=pjson'
 d=load(u); print('PROBE',name,'ERROR',d.get('error') or d.get('_error'),'NAME',d.get('name'),'PIXEL',d.get('pixelSizeX'),d.get('pixelType'))
